import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate, conversion_rate_by_group, conversions_in_window,
    longest_conversion_streak, pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_none_counts_as_an_unconverted_session():
    assert conversion_rate([{'converted': True}, {'converted': None}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_last_duplicate_wins_before_sorting():
    events = parse_session_log(['a,4,1', 'z,2,1', 'b,1,0', 'a,2,0'])
    assert dedupe_sessions(events) == [events[2], events[3], events[1]]


def test_parse_flags_and_skip_non_records():
    lines = ['', '  ', '  # ignore', ' a , 1 , 1 ', ' b,2, 0', 'c ,3,  ']
    assert parse_session_log(lines) == [
        {'id': 'a', 'day': 1, 'converted': True},
        {'id': 'b', 'day': 2, 'converted': False},
        {'id': 'c', 'day': 3, 'converted': None},
    ]


@pytest.mark.parametrize('bad', ['a,1', 'a,1,0,x', 'a,no,1'])
def test_parse_error_counts_skipped_lines(bad):
    with pytest.raises(ValueError, match=r'line 4\b'):
        parse_session_log(['', 'x,0,0', ' # comment', bad])


def test_daily_range_and_windows():
    events = parse_session_log(['a,0,1', 'b,1,1', 'c,1,1', 'd,2,0', 'e,4,1'])
    counts = daily_conversion_counts(events, 1, 3)
    assert counts == [2, 0, 0]
    assert daily_conversion_counts(events, 3, 1) == []
    assert conversions_in_window(counts, 2) == 0
    assert conversions_in_window(counts, 0) == 0
    assert conversions_in_window(counts, 4) == 2


def test_summary_uses_session_weights_and_calendar_days():
    groups = {'a': parse_session_log(['x,1,1', 'y,1,0']),
              'b': parse_session_log(['z,4,1']), 'empty': []}
    assert pooled_conversion_rate(groups) == 2 / 3
    assert campaign_summary(groups, 2) == {'rate': 0.667, 'recent': 1, 'groups': 2}
    assert campaign_summary({'empty': []}, 2) == {'rate': 0.0, 'recent': 0, 'groups': 0}


def test_group_rates_and_ranking():
    groups = {g: [{'converted': value}] for g, value in [('z', True), ('b', True), ('a', False)]}
    groups['empty'] = []
    assert top_converting_groups(groups, 1) == ['b']
    assert top_converting_groups(groups, 5) == ['b', 'z', 'a']
    assert list(conversion_rate_by_group(groups).items()) == [
        ('a', 0.0), ('b', 1.0), ('empty', None), ('z', 1.0),
    ]


def test_streak_counts_only_consecutive_positive_days():
    assert longest_conversion_streak([]) == 0
    assert longest_conversion_streak([1, 0, 1, 3, -1, 1]) == 2
